pub const QUERY_TABLE_DESC: &str =
    r###"Query any ServiceNow table by name with flexible filtering"###;
pub const QUERY_TABLE_SCHEMA: &str = r###"{"properties":{"fields":{"description":"Comma-separated list of fields to return (optional)","type":"string"},"instance":{"description":"Configured ServiceNow instance name. Optional; uses the current instance when omitted.","type":"string"},"limit":{"default":25,"description":"Maximum number of records to return (default: 25)","type":"number"},"offset":{"description":"Number of records to skip for pagination (optional)","type":"number"},"order_by":{"description":"Field to sort by (e.g., \"created_on\" or \"-priority\" for descending) (optional)","type":"string"},"query":{"description":"ServiceNow encoded query string (e.g., \"state=1^priority=1\") (optional)","type":"string"},"table_name":{"description":"ServiceNow table name (e.g., \"incident\", \"sys_user\", \"cmdb_ci\") (required)","type":"string"}},"required":["table_name"],"type":"object"}"###;

pub const CREATE_RECORD_DESC: &str = r###"Create a record in any ServiceNow table by name. WARNING: For catalog_ui_policy_action table, fields ui_policy and catalog_variable cannot be set via REST API - use SN-Execute-Background-Script with setValue() after creation."###;
