pub const NATURAL_LANGUAGE_SEARCH_DESC: &str = r###"Search ServiceNow records using natural language queries. Converts human-readable queries into ServiceNow encoded queries and executes them. Supports: Priority (P1-P5, high/low), Assignment (assigned to me, unassigned, assigned to <name>), Dates (created today, last 7 days, recent), States (new/open/closed/in progress), Content (about SAP, containing error), Impact/Urgency (high/medium/low), Numbers (number is INC0012345). Examples: "find all P1 incidents", "show recent problems assigned to me", "high priority changes created last week", "open incidents about SAP", "unassigned P2 incidents created today". Returns both the parsed encoded query and matching records with pattern analysis."###;
pub const NATURAL_LANGUAGE_SEARCH_SCHEMA: &str = r###"{"properties":{"fields":{"description":"Comma-separated list of fields to return (optional)","type":"string"},"instance":{"description":"Configured ServiceNow instance name. Optional; uses the current instance when omitted.","type":"string"},"limit":{"default":25,"description":"Maximum number of records to return (default: 25)","type":"number"},"order_by":{"description":"Field to sort by (e.g., \"sys_created_on\" or \"-priority\" for descending) (optional)","type":"string"},"query":{"description":"Natural language query, at most 2048 characters (e.g., \"high priority incidents assigned to me\", \"recent problems about database\") (required)","maxLength":2048,"type":"string"},"show_patterns":{"default":true,"description":"Include pattern matching details in response (default: true)","type":"boolean"},"table":{"default":"incident","description":"Target ServiceNow table name (default: \"incident\"). Common tables: incident, problem, change_request, sys_user, cmdb_ci","type":"string"}},"required":["query"],"type":"object"}"###;

pub const BATCH_CREATE_DESC: &str = r###"Create multiple related records in one operation with variable references and transactional support. Reports progress during execution."###;
pub const BATCH_CREATE_SCHEMA: &str = r###"{"properties":{"instance":{"description":"Configured ServiceNow instance name. Optional; uses the current instance when omitted.","type":"string"},"operations":{"description":"Array of at most 100 create operations, validated as a whole before any write. Each operation can reference IDs saved by earlier operations via ${save_as_name} (or ${operation_N}); unknown or later names stay literal.","items":{"properties":{"data":{"description":"Record data (at most 65536 bytes as JSON)","type":"object"},"save_as":{"description":"Variable name to save sys_id as (optional)","pattern":"^[A-Za-z_][A-Za-z0-9_]{0,63}$","type":"string"},"table":{"description":"Table name","pattern":"^[A-Za-z0-9_]{1,80}$","type":"string"}},"required":["table","data"],"type":"object"},"maxItems":100,"type":"array"},"progress":{"default":true,"description":"Report progress notifications (default: true)","type":"boolean"},"transaction":{"default":true,"description":"All-or-nothing transaction (default: true)","type":"boolean"}},"required":["operations"],"type":"object"}"###;

pub const BATCH_UPDATE_DESC: &str = r###"Update multiple records efficiently in a single operation. Reports progress during execution."###;
pub const BATCH_UPDATE_SCHEMA: &str = r###"{"properties":{"instance":{"description":"Configured ServiceNow instance name. Optional; uses the current instance when omitted.","type":"string"},"progress":{"default":true,"description":"Report progress notifications (default: true)","type":"boolean"},"stop_on_error":{"default":false,"description":"Stop processing on first error (default: false)","type":"boolean"},"updates":{"description":"Array of at most 100 update operations, validated as a whole before any write","items":{"properties":{"data":{"description":"Fields to update (at most 65536 bytes as JSON)","type":"object"},"sys_id":{"description":"Record sys_id (32 lowercase hex characters)","pattern":"^[0-9a-f]{32}$","type":"string"},"table":{"description":"Table name","pattern":"^[A-Za-z0-9_]{1,80}$","type":"string"}},"required":["table","sys_id","data"],"type":"object"},"maxItems":100,"type":"array"}},"required":["updates"],"type":"object"}"###;
